package com.infineonbit.sustainablefarm.modules.producttransformation.integration.cropstorage.dto;

import com.fasterxml.jackson.annotation.JsonProperty;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.math.BigDecimal;

/**
 * DTO for Crop Storage Entry Response
 * Maps to Crop Storage module API-005 contract
 *
 * Contract from Crop Storage team:
 * Convention: snake_case
 * Fields: entry_id, batch_code (generated by Crop Storage, B26-01 format),
 *         batch_id, packaging_id, dried_quantity_kg, waste_quantity_kg,
 *         product_stage, storage_location_id, available_capacity_kg
 *
 * @author Abdoul Ben Fatao SANON
 * @version 1.0.0
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class CropStorageEntryResponse {

    @JsonProperty("entry_id")
    private Long entryId;

    @JsonProperty("batch_code")
    private String batchCode; // Generated by Crop Storage (B26-01 format)

    @JsonProperty("batch_id")
    private String batchId;

    @JsonProperty("packaging_id")
    private String packagingId;

    @JsonProperty("dried_quantity_kg")
    private BigDecimal driedQuantityKg;

    @JsonProperty("waste_quantity_kg")
    private BigDecimal wasteQuantityKg;

    @JsonProperty("product_stage")
    private String productStage;

    @JsonProperty("storage_location_id")
    private String storageLocationId;

    @JsonProperty("available_capacity_kg")
    private BigDecimal availableCapacityKg;
}
